import{_ as d}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as r,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const y=JSON.parse('{"title":"CodeBuddy 学习地图","description":"腾讯云 CodeBuddy 是一套共享账号额度、但入口完全不同的 AI 编程产品族：独立 IDE、编辑器插件、终端 CLI。本页是家族图和决策树——先分清形态，再决定学什么。","frontmatter":{"title":"CodeBuddy 学习地图","description":"腾讯云 CodeBuddy 是一套共享账号额度、但入口完全不同的 AI 编程产品族：独立 IDE、编辑器插件、终端 CLI。本页是家族图和决策树——先分清形态，再决定学什么。","domain":"product","tags":["coding-agent"],"role":"map"},"headers":[],"relativePath":"zh/products/codebuddy/index.md","filePath":"zh/products/codebuddy/index.md","lastUpdated":1787110548000}'),n={name:"zh/products/codebuddy/index.md"};function o(s,t,l,c,h,p){return r(),e("div",null,[...t[0]||(t[0]=[a(`<h1 id="codebuddy-学习地图" tabindex="-1">CodeBuddy 学习地图 <a class="header-anchor" href="#codebuddy-学习地图" aria-label="Permalink to &quot;CodeBuddy 学习地图&quot;">​</a></h1><blockquote><p>腾讯云代码助手 <strong>CodeBuddy</strong> 同时提供 <strong>IDE、插件、CLI</strong> 三种编程形态。官方原文（<a href="https://www.codebuddy.cn/docs/" target="_blank" rel="noreferrer">文档总览</a>、<a href="https://cloud.tencent.com/document/product/1831/134343" target="_blank" rel="noreferrer">腾讯云产品概述</a>）：</p><p>「产品支持 IDE、插件和 CLI 三种形态，覆盖从专业开发者到零基础用户的全场景需求。」</p></blockquote><p>本页是全景图和决策树——<strong>先分清形态，再决定学什么</strong>。安装步骤见 <a href="./codebuddy.html">上手教程</a>。</p><h2 id="产品家族" tabindex="-1">产品家族 <a class="header-anchor" href="#产品家族" aria-label="Permalink to &quot;产品家族&quot;">​</a></h2><p>文档站顶栏一级入口（2026-08-18 打开 <a href="https://www.codebuddy.cn/docs/" target="_blank" rel="noreferrer">codebuddy.cn/docs</a>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>腾讯云 / CodeBuddy 家族</span></span>
<span class="line"><span>├── CodeBuddy IDE — 独立编辑器，「对话即编程」</span></span>
<span class="line"><span>├── CodeBuddy 插件 — VS Code / JetBrains 等宿主里的扩展</span></span>
<span class="line"><span>├── CodeBuddy Code（CLI）— 终端 agent，命令 \`codebuddy\`</span></span>
<span class="line"><span>├── WorkBuddy — 办公工作台（本目录不写教程）</span></span>
<span class="line"><span>│   ├── WorkBuddy 小程序</span></span>
<span class="line"><span>│   └── WorkBuddy 移动端</span></span>
<span class="line"><span>└── 企业版 — SaaS 旗舰 / 专享版（本目录不写教程）</span></span>
<span class="line"><span>同厂其它 AI（本目录不写教程）</span></span>
<span class="line"><span>├── 元宝 — 通用助手</span></span>
<span class="line"><span>└── 混元 — 模型，不是编码产品</span></span></code></pre></div><table tabindex="0"><thead><tr><th>官方一级入口</th><th>是什么</th><th>官方 URL</th><th>本站去向</th></tr></thead><tbody><tr><td><strong>CodeBuddy IDE</strong></td><td>产设研一体工作台，主打「对话即编程」</td><td><a href="https://www.codebuddy.cn/docs/" target="_blank" rel="noreferrer">文档总览</a> · <a href="https://www.codebuddy.cn/docs/ide/Getting-Started/Installation" target="_blank" rel="noreferrer">安装</a> · <a href="https://www.codebuddy.cn/ide/" target="_blank" rel="noreferrer">下载</a></td><td><a href="./codebuddy.html#安装-ide">教程</a></td></tr><tr><td><strong>CodeBuddy 插件</strong></td><td>装进已有编辑器的 AI 辅助</td><td><a href="https://www.codebuddy.cn/docs/plugin/" target="_blank" rel="noreferrer">插件文档</a></td><td><a href="./codebuddy.html#安装-插件">教程</a></td></tr><tr><td><strong>CodeBuddy Code（CLI）</strong></td><td>终端里用自然语言驱动开发</td><td><a href="https://www.codebuddy.cn/docs/cli/" target="_blank" rel="noreferrer">CLI 文档</a> · <a href="https://www.codebuddy.cn/docs/cli/installation" target="_blank" rel="noreferrer">安装</a></td><td><a href="./codebuddy.html#安装-cli">教程</a></td></tr><tr><td><strong>WorkBuddy</strong></td><td>「全场景 AI 办公工作台。说出要求、开始执行任务、交付完整成果。」</td><td><a href="https://www.codebuddy.cn/docs/workbuddy/" target="_blank" rel="noreferrer">WorkBuddy 简介</a> · <a href="https://www.codebuddy.cn/work/" target="_blank" rel="noreferrer">官网 /work</a></td><td><strong>地图一行</strong>，不拆教程</td></tr><tr><td><strong>WorkBuddy 小程序</strong></td><td>WorkBuddy 的移动端入口之一</td><td><a href="https://www.codebuddy.cn/docs/workbuddymini/" target="_blank" rel="noreferrer">小程序简介</a></td><td><strong>地图一行</strong>，不拆教程</td></tr><tr><td><strong>WorkBuddy 移动端</strong></td><td>桌面 WorkBuddy 的配套 App</td><td><a href="https://www.codebuddy.cn/docs/workbuddyapp/" target="_blank" rel="noreferrer">移动端简介</a></td><td><strong>地图一行</strong>，不拆教程</td></tr><tr><td><strong>企业版</strong></td><td>SaaS 企业版（旗舰版）/ 专有云专享版</td><td><a href="https://www.codebuddy.cn/docs/ide/Codebuddy-enterprise-edition/Codebuddy-enterprise-purchase" target="_blank" rel="noreferrer">购买流程</a> · <a href="https://cloud.tencent.com/document/product/1831/134343" target="_blank" rel="noreferrer">云文档概述</a></td><td><strong>地图一行</strong>，不拆教程</td></tr><tr><td><strong>元宝</strong></td><td>腾讯通用 AI 助手</td><td><a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a></td><td><strong>地图一行</strong>（另 #76）</td></tr><tr><td><strong>混元</strong></td><td>腾讯自研大模型；CodeBuddy 可切换的模型之一</td><td><a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a> · <a href="https://cloud.tencent.com/product/tclm" target="_blank" rel="noreferrer">云产品 tclm</a></td><td><strong>地图一行</strong>（另 #77）</td></tr></tbody></table><p><strong>不是本站范围</strong>：微信、QQ、云主机、支付。Retrieve 时若官方 nav 冒出这些，标「非本站」即可。</p><p>官方形态对照（<a href="https://cloud.tencent.com/document/product/1831/134343" target="_blank" rel="noreferrer">产品概述</a>）：</p><table tabindex="0"><thead><tr><th></th><th><strong>CodeBuddy 插件</strong></th><th><strong>CodeBuddy IDE</strong></th><th><strong>CodeBuddy Code</strong></th></tr></thead><tbody><tr><td>需求用户</td><td>日常编码开发者 / 特定 IDE 使用者</td><td>产品 / 设计师 / 全栈开发 / 编程初学者</td><td>DevOps / 运维 / SRE / 资深开发者</td></tr><tr><td>核心优势</td><td>即插即用，零成本学习；融入现有工作流</td><td>产设研一体；CloudBase / EdgeOne Pages / CloudStudio</td><td>Shell / 文件 / 网络；无头环境；任务编排 / Sub Agent</td></tr><tr><td>使用指引</td><td>插件市场搜索 <strong>腾讯云代码助手</strong></td><td>国际版 <a href="https://www.codebuddy.ai/" target="_blank" rel="noreferrer">codebuddy.ai</a> · 国内版 <a href="https://copilot.tencent.com/ide" target="_blank" rel="noreferrer">copilot.tencent.com/ide</a></td><td><code>npm install -g @tencent-ai/codebuddy-code</code></td></tr></tbody></table><p>三种形态 <strong>共享同一账号的资源配额</strong>（<a href="https://www.codebuddy.cn/docs/cli/troubleshooting" target="_blank" rel="noreferrer">故障排查 · 额度共享</a>）。</p><h3 id="快速决策-我该用哪个" tabindex="-1">快速决策：我该用哪个？ <a class="header-anchor" href="#快速决策-我该用哪个" aria-label="Permalink to &quot;快速决策：我该用哪个？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我现在要干什么？</span></span>
<span class="line"><span>├── 已经有 VS Code / JetBrains / Visual Studio，只想要补全和对话</span></span>
<span class="line"><span>│   └── → 插件（市场搜「腾讯云代码助手」）</span></span>
<span class="line"><span>├── 要从一句话需求走到原型 / 设计稿 / 可部署应用</span></span>
<span class="line"><span>│   └── → IDE（对话即编程）</span></span>
<span class="line"><span>├── 工作在终端：脚本、CI、批量重构、无头自动化</span></span>
<span class="line"><span>│   └── → CodeBuddy Code（\`codebuddy\` / \`codebuddy -p\`）</span></span>
<span class="line"><span>├── 办公文档 / PPT / 本地文件批处理，不是对着仓库写代码</span></span>
<span class="line"><span>│   └── → WorkBuddy（本目录不教；去官方）</span></span>
<span class="line"><span>└── 通用聊天 / 搜索，不是编码产品</span></span>
<span class="line"><span>    └── → 元宝（本目录不教）</span></span></code></pre></div><p>三个最容易混的名字，先记住：</p><table tabindex="0"><thead><tr><th>容易混的</th><th>区别</th></tr></thead><tbody><tr><td><strong>CodeBuddy</strong> vs <strong>WorkBuddy</strong></td><td>前者写代码；后者是办公工作台</td></tr><tr><td><strong>编辑器插件</strong> vs <strong>CLI <code>plugin</code></strong></td><td>前者装进 VS Code；后者是 <code>codebuddy plugin install</code></td></tr><tr><td><strong>混元</strong> vs <strong>CodeBuddy</strong></td><td>混元是模型；CodeBuddy 是产品，官方还写支持 DeepSeek 等</td></tr></tbody></table><p>更多辨析见 <a href="./codebuddy-glossary.html">术语表</a>。</p><h2 id="该读哪一篇" tabindex="-1">该读哪一篇 <a class="header-anchor" href="#该读哪一篇" aria-label="Permalink to &quot;该读哪一篇&quot;">​</a></h2><p>本组文档按 <a href="https://diataxis.fr/" target="_blank" rel="noreferrer">Diataxis</a> 拆分：</p><table tabindex="0"><thead><tr><th>文档</th><th>类型</th><th>什么时候看</th></tr></thead><tbody><tr><td><a href="./codebuddy.html">上手教程</a></td><td>Tutorial</td><td>第一次用：装 IDE / 插件 / CLI → 登录 → 第一次对话</td></tr><tr><td><a href="./codebuddy-cookbook.html">实战 Cookbook</a></td><td>How-to</td><td>已经能跑，要抄 <code>/init</code>、print 模式、自定义命令、MCP、迁移</td></tr><tr><td><a href="./codebuddy-cheatsheet.html">Cheatsheet</a></td><td>Reference</td><td>查安装原文、CLI 命令、斜杠命令、键位</td></tr><tr><td><a href="./codebuddy-glossary.html">术语表</a></td><td>Explanation</td><td>形态、权限模式、<code>CODEBUDDY.md</code>、国内站 / 国际站</td></tr></tbody></table><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>读什么</th><th>目标</th></tr></thead><tbody><tr><td>1. 选对形态并装上</td><td><a href="./codebuddy.html">教程</a></td><td>15 分钟内在一种形态里完成登录</td></tr><tr><td>2. 跑通第一次任务</td><td><a href="./codebuddy.html">教程</a> 的第一次对话；CLI 先 <code>/init</code></td><td>敢让它读仓库或改一小处</td></tr><tr><td>3. 接到日常工作流</td><td><a href="./codebuddy-cookbook.html">Cookbook</a></td><td>print 模式、斜杠命令、MCP</td></tr><tr><td>4. 回查参数</td><td><a href="./codebuddy-cheatsheet.html">速查表</a></td><td>命令、flag、安装原文</td></tr><tr><td>5. 理清概念</td><td><a href="./codebuddy-glossary.html">术语表</a></td><td>不再把 WorkBuddy / 混元 / CLI plugin 当同一个东西</td></tr></tbody></table><h2 id="功能速查" tabindex="-1">功能速查 <a class="header-anchor" href="#功能速查" aria-label="Permalink to &quot;功能速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>在哪</th><th>官方出处</th></tr></thead><tbody><tr><td>行内补全、技术对话、<code>@workspace</code> / <code>#Codebase</code></td><td>插件</td><td><a href="https://cloud.tencent.com/document/product/1831/134343" target="_blank" rel="noreferrer">产品概述</a></td></tr><tr><td>自然语言 → PRD / 设计稿 / 代码 / 一键部署</td><td>IDE</td><td>同上</td></tr><tr><td>交互式 REPL、<code>codebuddy -p</code>、斜杠命令、MCP</td><td>CLI</td><td><a href="https://www.codebuddy.cn/docs/cli/quickstart" target="_blank" rel="noreferrer">快速开始</a> · <a href="https://www.codebuddy.cn/docs/cli/cli-reference" target="_blank" rel="noreferrer">CLI 参考</a></td></tr><tr><td>Skills / Hooks / 子代理 / Daemon</td><td>CLI（高级）</td><td><a href="https://www.codebuddy.cn/docs/cli/" target="_blank" rel="noreferrer">CLI 文档树</a></td></tr></tbody></table><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>目标</strong>：让前端工程师分清 CodeBuddy 的三种编程形态，并按官方步骤装上、登录、跑通第一次任务。</p><p><strong>非目标</strong>：</p><ul><li>不写元宝、混元、WorkBuddy 的完整教程</li><li>不写微信 / QQ 产品</li><li>不写模型内部机制</li><li>不把官网营销百分比当成实测结论</li></ul><h2 id="资源" tabindex="-1">资源 <a class="header-anchor" href="#资源" aria-label="Permalink to &quot;资源&quot;">​</a></h2><ul><li><a href="https://www.codebuddy.cn/docs/" target="_blank" rel="noreferrer">国内文档站</a></li><li><a href="https://www.codebuddy.ai/docs/" target="_blank" rel="noreferrer">国际文档站</a> · <a href="https://www.codebuddy.ai/docs/zh/" target="_blank" rel="noreferrer">中文镜像</a></li><li><a href="https://cloud.tencent.com/product/acc" target="_blank" rel="noreferrer">腾讯云产品页 acc</a></li><li><a href="https://www.codebuddy.cn/pricing/" target="_blank" rel="noreferrer">定价</a> — 页面是前端渲染；不要在本站抄未核过的套餐数字</li><li><a href="./codebuddy-cheatsheet.html#高质量信息源">Cheatsheet · 高质量信息源</a></li></ul>`,29)])])}const f=d(n,[["render",o]]);export{y as __pageData,f as default};
